/**
 * The /ai review ledger (#593): one row per merged pull request, counted from
 * its "## Review triage" comments. The comments are pinned in
 * `review-triage.json`, regenerated by `scripts/fetch-review-triage.sh`;
 * the counting rule is in `lib/review-ledger.mjs`.
 */
import triage from './review-triage.json';
import { ledgerRow } from '../lib/review-ledger.mjs';

export const ledger = triage.pulls.map(ledgerRow);
export const ledgerFetchedAt = triage.fetchedAt.slice(0, 10);
export const ledgerRepo = triage.repo;
